<script setup lang="ts">
import type { Preferences } from '../../../../packages/contracts/src/member';
const member=useMember();const preferences=ref<Preferences|null>(null),message=ref(''),busy=ref(false);
let request=0;onBeforeUnmount(()=>{request++;});
async function load(){if(busy.value)return;busy.value=true;message.value='';const version=++request;try{await member.refresh();if(!member.session.value||version!==request)return;const result=(await $fetch<{data:Preferences}>('/api/v1/me/preferences')).data;if(version===request)preferences.value=result;}catch(e){if(version===request)message.value=memberError(e);}finally{if(version===request)busy.value=false;}}
onMounted(load);
async function save(){if(!preferences.value||busy.value)return;busy.value=true;message.value='';try{const patch={...preferences.value} as Partial<Preferences>;delete patch.updatedAt;preferences.value=(await member.mutate<{data:Preferences}>('/api/v1/me/preferences','PATCH',patch)).data;window.dispatchEvent(new CustomEvent('aggregator:preferences',{detail:preferences.value}));message.value='Preferences saved to your account.';}catch(e){message.value=memberError(e);}finally{busy.value=false;}}
useHead({title:'Preferences — The Aggregator'});
</script>
<template><MemberFrame><h1>Preferences</h1><p v-if="!member.checked.value">Checking your session…</p><p v-else-if="!member.session.value">Sign in to save preferences. <NuxtLink to="/sign-in?returnTo=/preferences">Sign in</NuxtLink></p><form v-if="preferences" class="member-form" @submit.prevent="save"><h2>Reading</h2><ControlSelect label="Default Home edition" v-model="preferences.homeMode" :options="[{value:`editorial`,label:`Top stories`},{value:`following`,label:`For you`}]"/><ControlSelect label="Theme" :model-value="preferences.theme" :options="['system','light','dark'].map(value=>({value,label:value[0]!.toUpperCase()+value.slice(1)}))" :disabled="busy" @update:model-value="preferences.theme=$event as typeof preferences.theme"/><ControlSelect label="Text size" :model-value="preferences.textSize" :options="['small','standard','large'].map(value=>({value,label:value[0]!.toUpperCase()+value.slice(1)}))" :disabled="busy" @update:model-value="preferences.textSize=$event as typeof preferences.textSize"/><ControlSwitch v-model="preferences.reduceMotion" label="Reduce motion" :disabled="busy"/><h2>Radio and Newsroom</h2><ControlSelect label="Playback speed" :model-value="preferences.playbackSpeed" :options="[.75,1,1.25,1.5].map(value=>({value,label:value+'×'}))" :disabled="busy" @update:model-value="preferences.playbackSpeed=$event as typeof preferences.playbackSpeed"/><ControlSelect label="Default presenters" :model-value="preferences.anchorCount" :options="[{value:1,label:'One presenter'},{value:2,label:'Two presenters'}]" :disabled="busy" @update:model-value="preferences.anchorCount=$event as typeof preferences.anchorCount"/><ControlSelect label="Narration voice" :model-value="preferences.narrationVoice" :options="[{value:'prepared',label:'Prepared local voices'}]" :disabled="busy" @update:model-value="preferences.narrationVoice=$event as typeof preferences.narrationVoice"/><ControlSelect label="Media treatment" :model-value="preferences.mediaTreatment" :options="[{value:'narration_over_visual',label:'Narration over illustration'},{value:'clip_then_comment',label:'Clip, then commentary (where prepared)'}]" :disabled="busy" @update:model-value="preferences.mediaTreatment=$event as typeof preferences.mediaTreatment"/><p class="metadata">Preferences select existing recordings. A missing variant is shown as unavailable; no recording is generated by changing these settings.</p><ControlSwitch v-model="preferences.listeningHistory" label="Save listening progress to my account" :disabled="busy"/><button class="control control--primary" type="submit" :disabled="busy">{{ busy?'Saving…':'Save preferences' }}</button><button class="control control--quiet" type="button"  :disabled="busy" @click="load">Reload saved preferences</button></form><p class="member-status" role="status">{{ message }}</p><details><summary>Your interests</summary><InterestEditor/></details></MemberFrame></template>
